export interface VoiceCommand {
  patterns: string[];
  action: string;
  description: string;
  category: "navigation" | "quiz" | "general" | "accessibility";
  requiresQuiz?: boolean;
}

export interface VoiceCommandResult {
  command: string;
  action: string;
  confidence: number;
  parameters?: Record<string, any>;
}

export const VOICE_COMMANDS: VoiceCommand[] = [
  // Navigation commands
