interface VoiceStatusProps {
  isListening: boolean;
  isSupported: boolean;
  currentLanguage: "english" | "hindi";
}

export default function VoiceStatus({ isListening, isSupported, currentLanguage }: VoiceStatusProps) {
  const getStatusMessage = () => {
    if (!isSupported) {
      return currentLanguage === "english" 
        ? "Voice recognition not available in this browser"
        : "इस ब्राउज़र में वॉयस रिकग्निशन उपलब्ध नहीं है";
    }

    if (isListening) {
      return currentLanguage === "english"
        ? "Listening for voice commands..."
        : "वॉयस कमांड सुन रहा है...";
    }

    return currentLanguage === "english"
      ? "Voice commands active - Say 'Help' for available commands"
      : "वॉयस कमांड सक्रिय - उपलब्ध कमांड के लिए 'मदद' कहें";
  };

  const getStatusColor = () => {
    if (!isSupported) return "text-destructive";
    if (isListening) return "text-primary";
    return "text-accent";
  };

  const getIndicatorColor = () => {
    if (!isSupported) return "bg-destructive";
    if (isListening) return "bg-primary";
    return "bg-accent";
  };

  return (
    <div 
      className="px-6 py-3 bg-accent/10 border-b border-border" 
      id="voice-status" 
      aria-live="polite" 
      aria-atomic="true"
      data-testid="voice-status"
    >
      <div className="flex items-center space-x-3">
        <div 
          className={`w-3 h-3 rounded-full ${getIndicatorColor()} ${isListening ? 'voice-pulse' : ''}`} 
          aria-hidden="true"
        ></div>
        <span className={`text-sm font-medium ${getStatusColor()}`}>
          {getStatusMessage()}
        </span>
      </div>
    </div>
  );
}

import * as React from "react"

const MOBILE_BREAKPOINT = 768

export function useIsMobile() {
  const [isMobile, setIsMobile] = React.useState<boolean | undefined>(undefined)

  React.useEffect(() => {
    const mql = window.matchMedia(`(max-width: ${MOBILE_BREAKPOINT - 1}px)`)
    const onChange = () => {
      setIsMobile(window.innerWidth < MOBILE_BREAKPOINT)
    }
    mql.addEventListener("change", onChange)
    setIsMobile(window.innerWidth < MOBILE_BREAKPOINT)
    return () => mql.removeEventListener("change", onChange)
  }, [])

  return !!isMobile
}

import { useState, useEffect, useCallback } from "react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { apiRequest } from "@/lib/queryClient";
import { toast } from "@/hooks/use-toast";
import type { ExamPack, Question, QuizSession } from "@shared/schema";

interface OfflineStorageData {
  examPacks: ExamPack[];
  questions: Record<string, Question[]>;
  quizSessions: QuizSession[];
  lastSync: Date;
}

interface UseOfflineStorageReturn {
  // Data state
  isOnline: boolean;
  offlineData: OfflineStorageData;
  downloadedPacks: string[];

  // Storage operations
  downloadPack: (packId: string) => Promise<void>;
  removePack: (packId: string) => Promise<void>;
  getOfflineQuestions: (packId: string) => Question[];

  // Quiz session management
  saveQuizSession: (session: QuizSession) => Promise<void>;
  loadQuizSession: (packId: string) => QuizSession | null;
  clearQuizSession: (packId: string) => Promise<void>;

  // Sync operations
  syncData: () => Promise<void>;
  getStorageInfo: () => { used: number; available: number; packs: number };

  // Loading states
  isDownloading: boolean;
  isSyncing: boolean;
}

const STORAGE_KEY = "gyansetu_offline_data";
const STORAGE_VERSION = "1.0";

export function useOfflineStorage(userId: string): UseOfflineStorageReturn {
  const [isOnline, setIsOnline] = useState(navigator.onLine);
  const [offlineData, setOfflineData] = useState<OfflineStorageData>({
    examPacks: [],
    questions: {},
    quizSessions: [],
    lastSync: new Date(0)
  });
  const [isDownloading, setIsDownloading] = useState(false);
  const [isSyncing, setIsSyncing] = useState(false);

  const queryClient = useQueryClient();

  // Monitor online status
  useEffect(() => {
    const handleOnline = () => setIsOnline(true);
    const handleOffline = () => setIsOnline(false);

    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);

    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, []);

  // Load offline data from localStorage on mount
  useEffect(() => {
    loadOfflineData();
  }, []);

  const loadOfflineData = useCallback(() => {
    try {
      const stored = localStorage.getItem(STORAGE_KEY);
      if (stored) {
        const parsed = JSON.parse(stored);
        if (parsed.version === STORAGE_VERSION) {
          setOfflineData({
            ...parsed.data,
            lastSync: new Date(parsed.data.lastSync)
          });
        }
      }
    } catch (error) {
      console.error("Error loading offline data:", error);
      toast({
        title: "Storage Error",
        description: "Failed to load offline data",
        variant: "destructive"
      });
    }
  }, []);

  const saveOfflineData = useCallback((data: OfflineStorageData) => {
    try {
      const toStore = {
        version: STORAGE_VERSION,
        data: {
          ...data,
          lastSync: data.lastSync.toISOString()
        }
      };
      localStorage.setItem(STORAGE_KEY, JSON.stringify(toStore));
      setOfflineData(data);
    } catch (error) {
      console.error("Error saving offline data:", error);
      toast({
        title: "Storage Error",
        description: "Failed to save offline data",
        variant: "destructive"
      });
    }
  }, []);

  // Download pack mutation
  const downloadPackMutation = useMutation({
    mutationFn: async (packId: string) => {
      const [packResponse, questionsResponse] = await Promise.all([
        apiRequest("GET", `/api/exam-packs/${packId}`, undefined),
        apiRequest("GET", `/api/exam-packs/${packId}/questions`, undefined)
      ]);

      const packData = await packResponse.json();
      const questionsData = await questionsResponse.json();

      return {
        examPack: packData.examPack,
        questions: questionsData.questions
      };
    },
    onSuccess: (data, packId) => {
      const newOfflineData = {
        ...offlineData,
        examPacks: [...offlineData.examPacks.filter(p => p.id !== packId), data.examPack],
        questions: {
          ...offlineData.questions,
          [packId]: data.questions
        },
        lastSync: new Date()
      };

      saveOfflineData(newOfflineData);

      // Mark as downloaded on server
      apiRequest("POST", `/api/users/${userId}/offline/${packId}`, {})
        .then(() => {
          queryClient.invalidateQueries({ queryKey: ["/api/users", userId, "offline"] });
        })
        .catch(console.error);

      toast({
        title: "Download Complete",
        description: `${data.examPack.title} is now available offline`
      });
    },
    onError: (error) => {
      console.error("Download error:", error);
      toast({
        title: "Download Failed",
        description: "Failed to download exam pack",
        variant: "destructive"
      });
    }
  });

  const downloadPack = useCallback(async (packId: string) => {
    if (!isOnline) {
      toast({
        title: "No Internet Connection",
        description: "Please connect to the internet to download content",
        variant: "destructive"
      });
      return;
    }

    setIsDownloading(true);
    try {
      await downloadPackMutation.mutateAsync(packId);
    } finally {
      setIsDownloading(false);
    }
  }, [isOnline, downloadPackMutation]);

  const removePack = useCallback(async (packId: string) => {
    const newOfflineData = {
      ...offlineData,
      examPacks: offlineData.examPacks.filter(p => p.id !== packId),
      questions: Object.fromEntries(
        Object.entries(offlineData.questions).filter(([id]) => id !== packId)
      ),
      quizSessions: offlineData.quizSessions.filter(s => s.examPackId !== packId)
    };

    saveOfflineData(newOfflineData);

    toast({
      title: "Pack Removed",
      description: "Exam pack removed from offline storage"
    });
  }, [offlineData, saveOfflineData]);

  const getOfflineQuestions = useCallback((packId: string): Question[] => {
    return offlineData.questions[packId] || [];
  }, [offlineData.questions]);

  const saveQuizSession = useCallback(async (session: QuizSession) => {
    const newSessions = offlineData.quizSessions.filter(s => s.examPackId !== session.examPackId);
    newSessions.push(session);

    const newOfflineData = {
      ...offlineData,
      quizSessions: newSessions
    };

    saveOfflineData(newOfflineData);
  }, [offlineData, saveOfflineData]);

  const loadQuizSession = useCallback((packId: string): QuizSession | null => {
    return offlineData.quizSessions.find(s => s.examPackId === packId) || null;
  }, [offlineData.quizSessions]);

  const clearQuizSession = useCallback(async (packId: string) => {
    const newOfflineData = {
      ...offlineData,
      quizSessions: offlineData.quizSessions.filter(s => s.examPackId !== packId)
    };

    saveOfflineData(newOfflineData);
  }, [offlineData, saveOfflineData]);

  const syncData = useCallback(async () => {
    if (!isOnline) {
      toast({
        title: "No Internet Connection",
        description: "Cannot sync while offline",
        variant: "destructive"
      });
      return;
    }

    setIsSyncing(true);
    try {
      // Sync any pending quiz sessions or progress
      // This would involve sending local data to server
      const newOfflineData = {
        ...offlineData,
        lastSync: new Date()
      };

      saveOfflineData(newOfflineData);

      toast({
        title: "Sync Complete",
        description: "Your progress has been synchronized"
      });
    } catch (error) {
      console.error("Sync error:", error);
      toast({
        title: "Sync Failed",
        description: "Failed to synchronize data",
        variant: "destructive"
      });
    } finally {
      setIsSyncing(false);
    }
  }, [isOnline, offlineData, saveOfflineData]);

  const getStorageInfo = useCallback(() => {
    try {
      // Estimate storage usage
      const dataSize = new Blob([JSON.stringify(offlineData)]).size;
      const availableStorage = navigator.storage && navigator.storage.estimate 
        ? 50 * 1024 * 1024 // 50MB estimate if API not available
        : 50 * 1024 * 1024;

      return {
        used: Math.round(dataSize / 1024 / 1024 * 100) / 100, // MB
        available: Math.round(availableStorage / 1024 / 1024), // MB
        packs: offlineData.examPacks.length
      };
    } catch (error) {
      return { used: 0, available: 50, packs: 0 };
    }
  }, [offlineData]);

  const downloadedPacks = offlineData.examPacks.map(pack => pack.id);

  return {
    isOnline,
    offlineData,
    downloadedPacks,
    downloadPack,
    removePack,
    getOfflineQuestions,
    saveQuizSession,
    loadQuizSession,
    clearQuizSession,
    syncData,
    getStorageInfo,
    isDownloading,
    isSyncing
  };
}

import { useState, useCallback, useRef, useEffect } from "react";

export function useSpeechRecognition() {
  const [isListening, setIsListening] = useState(false);
  const [transcript, setTranscript] = useState("");
  const [error, setError] = useState<string | null>(null);

  const recognitionRef = useRef<SpeechRecognition | null>(null);
  const timeoutRef = useRef<NodeJS.Timeout | null>(null);

  // Check if speech recognition is supported
  const isSupported = 'webkitSpeechRecognition' in window || 'SpeechRecognition' in window;

  // Initialize speech recognition
  useEffect(() => {
    if (!isSupported) return;

    const SpeechRecognition = window.SpeechRecognition || window.webkitSpeechRecognition;
    const recognition = new SpeechRecognition();

    recognition.continuous = false;
    recognition.interimResults = false;
    recognition.lang = 'en-US';
    recognition.maxAlternatives = 1;

    recognition.onstart = () => {
      setIsListening(true);
      setError(null);
    };

    recognition.onresult = (event: SpeechRecognitionEvent) => {
      const lastResult = event.results[event.results.length - 1];
      if (lastResult.isFinal) {
        const transcript = lastResult[0].transcript.trim().toLowerCase();
        setTranscript(transcript);
        console.log("Speech recognition result:", transcript);
      }
    };

    recognition.onerror = (event: SpeechRecognitionErrorEvent) => {
      console.error("Speech recognition error:", event.error);
      setError(event.error);
      setIsListening(false);
    };

    recognition.onend = () => {
      setIsListening(false);
    };

    recognitionRef.current = recognition;

    return () => {
      if (recognition) {
        recognition.abort();
      }
    };
  }, [isSupported]);

  const startListening = useCallback(() => {
    if (!isSupported || !recognitionRef.current) {
      setError("Speech recognition not supported");
      return;
    }

    try {
      setTranscript("");
      setError(null);
      recognitionRef.current.start();

      // Auto-stop after 10 seconds
      timeoutRef.current = setTimeout(() => {
        stopListening();
      }, 10000);
    } catch (err) {
      console.error("Error starting speech recognition:", err);
      setError("Failed to start speech recognition");
    }
  }, [isSupported]);

  const stopListening = useCallback(() => {
    if (recognitionRef.current) {
      recognitionRef.current.stop();
    }

    if (timeoutRef.current) {
      clearTimeout(timeoutRef.current);
      timeoutRef.current = null;
    }

    setIsListening(false);
  }, []);

  // Clear timeout on unmount
  useEffect(() => {
    return () => {
      if (timeoutRef.current) {
        clearTimeout(timeoutRef.current);
      }
    };
  }, []);

  return {
    isListening,
    transcript,
    error,
    startListening,
    stopListening,
    isSupported
  };
}

import * as React from "react"

import type {
  ToastActionElement,
  ToastProps,
} from "@/components/ui/toast"

const TOAST_LIMIT = 1
const TOAST_REMOVE_DELAY = 1000000

type ToasterToast = ToastProps & {
  id: string
  title?: React.ReactNode
  description?: React.ReactNode
  action?: ToastActionElement
}

const actionTypes = {
  ADD_TOAST: "ADD_TOAST",
  UPDATE_TOAST: "UPDATE_TOAST",
  DISMISS_TOAST: "DISMISS_TOAST",
  REMOVE_TOAST: "REMOVE_TOAST",
} as const

let count = 0

function genId() {
  count = (count + 1) % Number.MAX_SAFE_INTEGER
  return count.toString()
}

type ActionType = typeof actionTypes

type Action =
  | {
      type: ActionType["ADD_TOAST"]
      toast: ToasterToast
    }
  | {
      type: ActionType["UPDATE_TOAST"]
      toast: Partial<ToasterToast>
    }
  | {
      type: ActionType["DISMISS_TOAST"]
      toastId?: ToasterToast["id"]
    }
  | {
      type: ActionType["REMOVE_TOAST"]
      toastId?: ToasterToast["id"]
    }

interface State {
  toasts: ToasterToast[]
}

const toastTimeouts = new Map<string, ReturnType<typeof setTimeout>>()

const addToRemoveQueue = (toastId: string) => {
  if (toastTimeouts.has(toastId)) {
    return
  }

  const timeout = setTimeout(() => {
    toastTimeouts.delete(toastId)
    dispatch({
      type: "REMOVE_TOAST",
      toastId: toastId,
    })
  }, TOAST_REMOVE_DELAY)

  toastTimeouts.set(toastId, timeout)
}

export const reducer = (state: State, action: Action): State => {
  switch (action.type) {
    case "ADD_TOAST":
      return {
        ...state,
        toasts: [action.toast, ...state.toasts].slice(0, TOAST_LIMIT),
      }

    case "UPDATE_TOAST":
      return {
        ...state,
        toasts: state.toasts.map((t) =>
          t.id === action.toast.id ? { ...t, ...action.toast } : t
        ),
      }

    case "DISMISS_TOAST": {
      const { toastId } = action

      // ! Side effects ! - This could be extracted into a dismissToast() action,
      // but I'll keep it here for simplicity
      if (toastId) {
        addToRemoveQueue(toastId)
      } else {
        state.toasts.forEach((toast) => {
          addToRemoveQueue(toast.id)
        })
      }

      return {
        ...state,
        toasts: state.toasts.map((t) =>
          t.id === toastId || toastId === undefined
            ? {
                ...t,
                open: false,
              }
            : t
        ),
      }
    }
    case "REMOVE_TOAST":
      if (action.toastId === undefined) {
        return {
          ...state,
          toasts: [],
        }
      }
      return {
        ...state,
        toasts: state.toasts.filter((t) => t.id !== action.toastId),
      }
  }
}

const listeners: Array<(state: State) => void> = []

let memoryState: State = { toasts: [] }

function dispatch(action: Action) {
  memoryState = reducer(memoryState, action)
  listeners.forEach((listener) => {
    listener(memoryState)
  })
}

type Toast = Omit<ToasterToast, "id">

function toast({ ...props }: Toast) {
  const id = genId()

  const update = (props: ToasterToast) =>
    dispatch({
      type: "UPDATE_TOAST",
      toast: { ...props, id },
    })
  const dismiss = () => dispatch({ type: "DISMISS_TOAST", toastId: id })

  dispatch({
    type: "ADD_TOAST",
    toast: {
      ...props,
      id,
      open: true,
      onOpenChange: (open) => {
        if (!open) dismiss()
      },
    },
  })

  return {
    id: id,
    dismiss,
    update,
  }
}

function useToast() {
  const [state, setState] = React.useState<State>(memoryState)

  React.useEffect(() => {
    listeners.push(setState)
    return () => {
      const index = listeners.indexOf(setState)
      if (index > -1) {
        listeners.splice(index, 1)
      }
    }
  }, [state])

  return {
    ...state,
    toast,
    dismiss: (toastId?: string) => dispatch({ type: "DISMISS_TOAST", toastId }),
  }
}

export { useToast, toast }

import { useState, useCallback, useRef } from "react";

export function useTTS() {
  const [isSpeaking, setIsSpeaking] = useState(false);
  const currentUtteranceRef = useRef<SpeechSynthesisUtterance | null>(null);

  const speak = useCallback((text: string, language: "english" | "hindi" = "english") => {
    if (!('speechSynthesis' in window)) {
      console.warn("Speech synthesis not supported in this browser");
      return;
    }

    // Stop any current speech
    if (currentUtteranceRef.current) {
      speechSynthesis.cancel();
    }

    const utterance = new SpeechSynthesisUtterance(text);

    // Set language and voice properties
    utterance.lang = language === "hindi" ? "hi-IN" : "en-US";
    utterance.rate = 0.9;
    utterance.pitch = 1.0;
    utterance.volume = 1.0;

    // Event handlers
    utterance.onstart = () => {
      setIsSpeaking(true);
    };

    utterance.onend = () => {
      setIsSpeaking(false);
      currentUtteranceRef.current = null;
    };

    utterance.onerror = (event) => {
      console.error("Speech synthesis error:", event.error);
      setIsSpeaking(false);
      currentUtteranceRef.current = null;
    };

    currentUtteranceRef.current = utterance;
    speechSynthesis.speak(utterance);

    // Update audio announcements div for screen readers
    const announcementElement = document.getElementById("current-announcement");
    if (announcementElement) {
      announcementElement.textContent = text;
    }
  }, []);

  const stop = useCallback(() => {
    if ('speechSynthesis' in window) {
      speechSynthesis.cancel();
      setIsSpeaking(false);
      currentUtteranceRef.current = null;
    }
  }, []);

  const isSupported = 'speechSynthesis' in window;

  return {
    speak,
    stop,
    isSpeaking,
    isSupported
  };
}

export interface AccessibilitySettings {
  highContrast: boolean;
  largeText: boolean;
  reduceMotion: boolean;
  speechRate: number;
  speechPitch: number;
  speechVolume: number;
  keyboardNavigation: boolean;
  screenReaderOptimized: boolean;
}

export interface AccessibilityAnnouncement {
  message: string;
  priority: "polite" | "assertive" | "off";
  language?: "english" | "hindi";
  delay?: number;
}

export class AccessibilityManager {
  private settings: AccessibilitySettings;
  private announceQueue: AccessibilityAnnouncement[] = [];
  private isAnnouncing: boolean = false;
  private lastAnnouncement: string = "";

  constructor(initialSettings?: Partial<AccessibilitySettings>) {
    this.settings = {
      highContrast: false,
      largeText: false,
      reduceMotion: false,
      speechRate: 0.9,
      speechPitch: 1.0,
      speechVolume: 1.0,
      keyboardNavigation: true,
      screenReaderOptimized: true,
      ...initialSettings
    };

    this.initializeAccessibility();
  }

  private initializeAccessibility(): void {
    // Apply initial settings
    this.applyContrastMode();
    this.applyTextSize();
    this.applyMotionPreferences();
    this.setupKeyboardNavigation();
    this.setupFocusManagement();
    this.detectUserPreferences();
  }

  private detectUserPreferences(): void {
    // Detect system preferences
    if (window.matchMedia('(prefers-contrast: high)').matches) {
      this.updateSetting('highContrast', true);
    }

    if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) {
      this.updateSetting('reduceMotion', true);
    }

    // Listen for preference changes
    window.matchMedia('(prefers-contrast: high)').addEventListener('change', (e) => {
      this.updateSetting('highContrast', e.matches);
    });

    window.matchMedia('(prefers-reduced-motion: reduce)').addEventListener('change', (e) => {
      this.updateSetting('reduceMotion', e.matches);
    });
  }

  updateSetting<K extends keyof AccessibilitySettings>(
    setting: K, 
    value: AccessibilitySettings[K]
  ): void {
    this.settings[setting] = value;

    // Apply setting immediately
    switch (setting) {
      case 'highContrast':
        this.applyContrastMode();
        break;
      case 'largeText':
        this.applyTextSize();
        break;
      case 'reduceMotion':
        this.applyMotionPreferences();
        break;
    }

    // Save to localStorage
    localStorage.setItem('gyansetu_accessibility', JSON.stringify(this.settings));
  }

  getSettings(): AccessibilitySettings {
    return { ...this.settings };
  }

  private applyContrastMode(): void {
    const root = document.documentElement;

    if (this.settings.highContrast) {
      root.setAttribute('data-contrast', 'high');
      root.style.setProperty('--accessibility-contrast', '1');
    } else {
      root.removeAttribute('data-contrast');
      root.style.removeProperty('--accessibility-contrast');
    }
  }

  private applyTextSize(): void {
    const root = document.documentElement;

    if (this.settings.largeText) {
      root.style.setProperty('--accessibility-font-scale', '1.25');
      root.classList.add('large-text');
    } else {
      root.style.setProperty('--accessibility-font-scale', '1');
      root.classList.remove('large-text');
    }
  }

  private applyMotionPreferences(): void {
    const root = document.documentElement;

    if (this.settings.reduceMotion) {
      root.style.setProperty('--accessibility-motion', 'reduce');
      root.classList.add('reduce-motion');
    } else {
      root.style.setProperty('--accessibility-motion', 'auto');
      root.classList.remove('reduce-motion');
    }
  }

  private setupKeyboardNavigation(): void {
    if (!this.settings.keyboardNavigation) return;

    // Ensure all interactive elements are focusable
    const interactiveElements = document.querySelectorAll(
      'button, [role="button"], a, input, select, textarea, [tabindex]'
    );

    interactiveElements.forEach((element) => {
      if (!element.hasAttribute('tabindex')) {
        element.setAttribute('tabindex', '0');
      }
    });

    // Add keyboard event handlers
    document.addEventListener('keydown', this.handleKeyboardNavigation.bind(this));
  }

  private handleKeyboardNavigation(event: KeyboardEvent): void {
    // ESC key handling
    if (event.key === 'Escape') {
      this.handleEscapeKey();
    }

    // Arrow key navigation for custom components
    if (['ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight'].includes(event.key)) {
      this.handleArrowKeyNavigation(event);
    }

    // Space and Enter for activation
    if (event.key === ' ' || event.key === 'Enter') {
      this.handleActivationKeys(event);
    }
  }

  private handleEscapeKey(): void {
    // Close any open modals, menus, etc.
    const openElements = document.querySelectorAll('[aria-expanded="true"]');
    openElements.forEach((element) => {
      element.setAttribute('aria-expanded', 'false');
    });

    // Announce escape action
    this.announce("Escaped to main content", "polite");
  }

  private handleArrowKeyNavigation(event: KeyboardEvent): void {
    const focusedElement = document.activeElement as HTMLElement;

    // Handle radio group navigation
    if (focusedElement?.getAttribute('role') === 'radio') {
      event.preventDefault();
      this.navigateRadioGroup(event.key, focusedElement);
    }

    // Handle menu navigation
    if (focusedElement?.closest('[role="menu"]')) {
      event.preventDefault();
      this.navigateMenu(event.key, focusedElement);
    }
  }

  private handleActivationKeys(event: KeyboardEvent): void {
    const target = event.target as HTMLElement;

    if (target.getAttribute('role') === 'button' && event.key === ' ') {
      event.preventDefault();
      target.click();
    }
  }

  private navigateRadioGroup(key: string, currentElement: HTMLElement): void {
    const radioGroup = currentElement.closest('[role="radiogroup"]');
    if (!radioGroup) return;

    const radios = Array.from(radioGroup.querySelectorAll('[role="radio"]'));
    const currentIndex = radios.indexOf(currentElement);

    let nextIndex: number;
    if (key === 'ArrowDown' || key === 'ArrowRight') {
      nextIndex = (currentIndex + 1) % radios.length;
    } else {
      nextIndex = (currentIndex - 1 + radios.length) % radios.length;
    }

    (radios[nextIndex] as HTMLElement).focus();
  }

  private navigateMenu(key: string, currentElement: HTMLElement): void {
    const menu = currentElement.closest('[role="menu"]');
    if (!menu) return;

    const menuItems = Array.from(menu.querySelectorAll('[role="menuitem"]'));
    const currentIndex = menuItems.indexOf(currentElement);

    let nextIndex: number;
    if (key === 'ArrowDown') {
      nextIndex = (currentIndex + 1) % menuItems.length;
    } else if (key === 'ArrowUp') {
      nextIndex = (currentIndex - 1 + menuItems.length) % menuItems.length;
    } else {
      return;
    }

    (menuItems[nextIndex] as HTMLElement).focus();
  }

  private setupFocusManagement(): void {
    // Trap focus in modals
    document.addEventListener('focusin', (event) => {
      const modal = document.querySelector('[role="dialog"][aria-modal="true"]');
      if (modal && !modal.contains(event.target as Node)) {
        const firstFocusable = modal.querySelector(
          'button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])'
        ) as HTMLElement;
        firstFocusable?.focus();
      }
    });

    // Announce focus changes for screen readers
    document.addEventListener('focusin', (event) => {
      const target = event.target as HTMLElement;
      const ariaLabel = target.getAttribute('aria-label');
      const ariaLabelledBy = target.getAttribute('aria-labelledby');

      if (ariaLabel) {
        this.announce(`Focused: ${ariaLabel}`, "polite", undefined, 100);
      } else if (ariaLabelledBy) {
        const labelElement = document.getElementById(ariaLabelledBy);
        if (labelElement) {
          this.announce(`Focused: ${labelElement.textContent}`, "polite", undefined, 100);
        }
      }
    });
  }

  announce(
    message: string, 
    priority: "polite" | "assertive" | "off" = "polite",
    language: "english" | "hindi" = "english",
    delay: number = 0
  ): void {
    const announcement: AccessibilityAnnouncement = {
      message,
      priority,
      language,
      delay
    };

    this.announceQueue.push(announcement);

    if (!this.isAnnouncing) {
      this.processAnnounceQueue();
    }
  }

  private async processAnnounceQueue(): Promise<void> {
    if (this.announceQueue.length === 0) {
      this.isAnnouncing = false;
      return;
    }

    this.isAnnouncing = true;
    const announcement = this.announceQueue.shift()!;

    // Add delay if specified
    if (announcement.delay) {
      await new Promise(resolve => setTimeout(resolve, announcement.delay));
    }

    // Update screen reader announcement area
    this.updateScreenReaderAnnouncement(announcement);

    // Also use speech synthesis if available
    if ('speechSynthesis' in window && this.settings.screenReaderOptimized) {
      this.speakAnnouncement(announcement);
    }

    this.lastAnnouncement = announcement.message;

    // Process next announcement after a brief delay
    setTimeout(() => {
      this.processAnnounceQueue();
    }, 100);
  }

  private updateScreenReaderAnnouncement(announcement: AccessibilityAnnouncement): void {
    const announcementElement = document.getElementById('current-announcement');
    if (announcementElement) {
      // Clear first to ensure screen readers notice the change
      announcementElement.textContent = '';

      // Set the announcement after a brief delay
      setTimeout(() => {
        announcementElement.textContent = announcement.message;
      }, 10);
    }

    // Also update the live region priority
    const liveRegion = document.getElementById('audio-announcements');
    if (liveRegion) {
      liveRegion.setAttribute('aria-live', announcement.priority);
    }
  }

  private speakAnnouncement(announcement: AccessibilityAnnouncement): void {
    const utterance = new SpeechSynthesisUtterance(announcement.message);
    utterance.lang = announcement.language === "hindi" ? "hi-IN" : "en-US";
    utterance.rate = this.settings.speechRate;
    utterance.pitch = this.settings.speechPitch;
    utterance.volume = this.settings.speechVolume;

    speechSynthesis.speak(utterance);
  }

  getLastAnnouncement(): string {
    return this.lastAnnouncement;
  }

  repeatLastAnnouncement(): void {
    if (this.lastAnnouncement) {
      this.announce(this.lastAnnouncement, "assertive");
    }
  }

  // Color contrast utilities
  static checkColorContrast(foreground: string, background: string): number {
    const getLuminance = (color: string): number => {
      // Convert color to RGB values
      const rgb = this.hexToRgb(color);
      if (!rgb) return 0;

      // Calculate relative luminance
      const [r, g, b] = [rgb.r, rgb.g, rgb.b].map(c => {
        c = c / 255;
        return c <= 0.03928 ? c / 12.92 : Math.pow((c + 0.055) / 1.055, 2.4);
      });

      return 0.2126 * r + 0.7152 * g + 0.0722 * b;
    };

    const l1 = getLuminance(foreground);
    const l2 = getLuminance(background);
    const lighter = Math.max(l1, l2);
    const darker = Math.min(l1, l2);

    return (lighter + 0.05) / (darker + 0.05);
  }

  private static hexToRgb(hex: string): { r: number; g: number; b: number } | null {
    const result = /^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(hex);
    return result ? {
      r: parseInt(result[1], 16),
      g: parseInt(result[2], 16),
      b: parseInt(result[3], 16)
    } : null;
  }

  // Touch target utilities
  static ensureTouchTargets(): void {
    const minTouchSize = 44; // 44px minimum as per WCAG
    const interactiveElements = document.querySelectorAll(
      'button, [role="button"], a, input[type="checkbox"], input[type="radio"]'
    );

    interactiveElements.forEach((element) => {
      const rect = element.getBoundingClientRect();

      if (rect.width < minTouchSize || rect.height < minTouchSize) {
        (element as HTMLElement).style.minWidth = `${minTouchSize}px`;
        (element as HTMLElement).style.minHeight = `${minTouchSize}px`;
        element.classList.add('touch-target');
      }
    });
  }

  // ARIA live region utilities
  createLiveRegion(id: string, priority: "polite" | "assertive" = "polite"): HTMLElement {
    const existing = document.getElementById(id);
    if (existing) return existing;

    const liveRegion = document.createElement('div');
    liveRegion.id = id;
    liveRegion.setAttribute('aria-live', priority);
    liveRegion.setAttribute('aria-atomic', 'true');
    liveRegion.className = 'sr-only';

    document.body.appendChild(liveRegion);
    return liveRegion;
  }

  // Form accessibility helpers
  static enhanceFormAccessibility(): void {
    // Add required indicators
    const requiredFields = document.querySelectorAll('[required]');
    requiredFields.forEach((field) => {
      field.setAttribute('aria-required', 'true');

      const label = document.querySelector(`label[for="${field.id}"]`);
      if (label && !label.textContent?.includes('*')) {
        label.innerHTML += ' <span aria-label="required">*</span>';
      }
    });

    // Add error associations
    const errorElements = document.querySelectorAll('[id$="-error"]');
    errorElements.forEach((error) => {
      const fieldId = error.id.replace('-error', '');
      const field = document.getElementById(fieldId);

      if (field) {
        field.setAttribute('aria-describedby', error.id);
        field.setAttribute('aria-invalid', 'true');
      }
    });
  }
}

// Create default instance
export const accessibilityManager = new AccessibilityManager();

// Utility functions
export function announceToScreenReader(
  message: string, 
  priority: "polite" | "assertive" = "polite"
): void {
  accessibilityManager.announce(message, priority);
}

export function repeatLastAnnouncement(): void {
  accessibilityManager.repeatLastAnnouncement();
}

export function setupAccessibilityFeatures(): void {
  // Initialize all accessibility features
  AccessibilityManager.ensureTouchTargets();
  AccessibilityManager.enhanceFormAccessibility();

  // Setup global keyboard shortcuts
  document.addEventListener('keydown', (event) => {
    // Alt + H for help
    if (event.altKey && event.key === 'h') {
      event.preventDefault();
      announceToScreenReader("Help: Press tab to navigate, space or enter to activate, escape to cancel", "assertive");
    }

    // Alt + R to repeat last announcement
    if (event.altKey && event.key === 'r') {
      event.preventDefault();
      repeatLastAnnouncement();
    }
  });
}

// Initialize accessibility features when module loads
if (typeof window !== 'undefined') {
  document.addEventListener('DOMContentLoaded', setupAccessibilityFeatures);
}

import { QueryClient, QueryFunction } from "@tanstack/react-query";

async function throwIfResNotOk(res: Response) {
  if (!res.ok) {
    const text = (await res.text()) || res.statusText;
    throw new Error(`${res.status}: ${text}`);
  }
}

export async function apiRequest(
  method: string,
  url: string,
  data?: unknown | undefined,
): Promise<Response> {
  const res = await fetch(url, {
    method,
    headers: data ? { "Content-Type": "application/json" } : {},
    body: data ? JSON.stringify(data) : undefined,
    credentials: "include",
  });

  await throwIfResNotOk(res);
  return res;
}

type UnauthorizedBehavior = "returnNull" | "throw";
export const getQueryFn: <T>(options: {
  on401: UnauthorizedBehavior;
}) => QueryFunction<T> =
  ({ on401: unauthorizedBehavior }) =>
  async ({ queryKey }) => {
    const res = await fetch(queryKey.join("/") as string, {
      credentials: "include",
    });

    if (unauthorizedBehavior === "returnNull" && res.status === 401) {
      return null;
    }

    await throwIfResNotOk(res);
    return await res.json();
  };

export const queryClient = new QueryClient({
  defaultOptions: {
    queries: {
